#include <math.h>

static int vec3_approx(const float a[3], float x, float y, float z)
{
    return fabsf(a[0] - x) < 0.001f &&
           fabsf(a[1] - y) < 0.001f &&
           fabsf(a[2] - z) < 0.001f;
}

static void test_sol_mover_parent_first_eval(void)
{
    struct s_base base;
    struct s_vary vary;
    struct b_path paths[3];
    struct b_body bodies[2];
    float p[3];

    memset(&base, 0, sizeof (base));
    memset(&vary, 0, sizeof (vary));
    memset(paths, 0, sizeof (paths));
    memset(bodies, 0, sizeof (bodies));

    /* Path 0: parent segment start, active */
    paths[0].p[0] = 0.0f;
    paths[0].p[1] = 0.0f;
    paths[0].p[2] = 0.0f;
    paths[0].e[0] = 1.0f;
    paths[0].t    = 1.0f;
    paths[0].tm   = 1000;
    paths[0].pi   = 1;
    paths[0].f    = 1;
    paths[0].p0   = -1;
    paths[0].p1   = -1;

    /* Path 1: parent segment end, loops back */
    paths[1].p[0] = 10.0f;
    paths[1].p[1] = 0.0f;
    paths[1].p[2] = 0.0f;
    paths[1].e[0] = 1.0f;
    paths[1].t    = 1.0f;
    paths[1].tm   = 1000;
    paths[1].pi   = 0;
    paths[1].f    = 1;
    paths[1].p0   = -1;
    paths[1].p1   = -1;

    /* Path 2: child node offset at (0, 5, 0), attached to Path 0, inactive */
    paths[2].p[0] = 0.0f;
    paths[2].p[1] = 5.0f;
    paths[2].p[2] = 0.0f;
    paths[2].e[0] = 1.0f;
    paths[2].t    = 1.0f;
    paths[2].tm   = 1000;
    paths[2].pi   = 2;
    paths[2].f    = 0;
    paths[2].p0   = 0;
    paths[2].p1   = -1;

    bodies[0].p0 = 0;
    bodies[0].p1 = -1;
    bodies[1].p0 = 2;
    bodies[1].p1 = -1;

    base.pc = 3;
    base.pv = paths;
    base.bc = 2;
    base.bv = bodies;

    if (!sol_load_vary(&vary, &base))
        exit(1);

    /* Initial evaluation at t = 0 */
    sol_body_p(p, &vary, vary.bv[0].mi, 0.0f);
    if (!vec3_approx(p, 0.0f, 0.0f, 0.0f))
        exit(1);

    sol_body_p(p, &vary, vary.bv[1].mi, 0.0f);
    if (!vec3_approx(p, 0.0f, 5.0f, 0.0f))
        exit(1);

    /* Advance simulation by 0.5s (parent moves to X=5) */
    sol_move_step(&vary, NULL, 0.5f, 500);

    /* Evaluate parent first (clearing parent's dirty flag) */
    sol_body_p(p, &vary, vary.bv[0].mi, 0.0f);
    if (!vec3_approx(p, 5.0f, 0.0f, 0.0f))
        exit(1);

    /* Evaluate child second: child world position must follow parent to X=5, Y=5 */
    sol_body_p(p, &vary, vary.bv[1].mi, 0.0f);
    if (!vec3_approx(p, 5.0f, 5.0f, 0.0f))
        exit(1);

    sol_free_vary(&vary);
}

